import * as THREE from 'three';
import {createBoard,pointAt,labelTexture} from './model.js';
export function initBoard(container){const scene=new THREE.Scene();scene.background=new THREE.Color('#171f2b');const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;container.appendChild(renderer.domElement);const camera=new THREE.PerspectiveCamera(35,1,.1,60);scene.add(new THREE.HemisphereLight('#e5efff','#313740',2.2));const light=new THREE.DirectionalLight('#fff1d9',3.5);light.position.set(-3,10,6);light.castShadow=true;light.shadow.mapSize.set(2048,2048);Object.assign(light.shadow.camera,{left:-7,right:7,top:7,bottom:-7,near:.5,far:30});light.shadow.bias=-.0003;light.shadow.normalBias=.03;light.shadow.radius=4;scene.add(light);const fill=new THREE.DirectionalLight('#91b8d9',1.2);fill.position.set(6,4,-4);scene.add(fill);const floor=new THREE.Mesh(new THREE.PlaneGeometry(200,200),new THREE.MeshStandardMaterial({color:'#171f2b',roughness:1}));floor.rotation.x=-Math.PI/2;floor.position.y=-.34;floor.receiveShadow=true;scene.add(floor);const board=createBoard();scene.add(board.group);let yaw=-.16,pitch=.87,distance=13.8,overhead=false,calm=matchMedia('(prefers-reduced-motion: reduce)').matches;let pointer=null,animation=null;let desiredPos=[0,0],active=0,won=false;const clock=new THREE.Clock();
function updateCamera(){const h=container.clientHeight,w=container.clientWidth;const aspect=w/Math.max(h,1);camera.aspect=aspect;camera.updateProjectionMatrix();const d=distance*(aspect<1.2?1.2/aspect:1);camera.position.set(Math.sin(yaw)*Math.cos(pitch)*d,Math.sin(pitch)*d,Math.cos(yaw)*Math.cos(pitch)*d);camera.lookAt(0,0,0);renderer.setSize(w,h,false);}
new ResizeObserver(updateCamera).observe(container);updateCamera();
container.addEventListener('pointerdown',e=>{if(e.button!==0)return;pointer={x:e.clientX,y:e.clientY};container.setPointerCapture(e.pointerId);});container.addEventListener('pointermove',e=>{if(!pointer)return;yaw-=(e.clientX-pointer.x)*.006;pitch=Math.max(.45,Math.min(1.53,pitch+(e.clientY-pointer.y)*.004));pointer={x:e.clientX,y:e.clientY};updateCamera();});const end=()=>{pointer=null};container.addEventListener('pointerup',end);container.addEventListener('pointercancel',end);container.addEventListener('wheel',e=>{e.preventDefault();distance=Math.min(19,Math.max(10,distance+e.deltaY*.009));updateCamera();},{passive:false});
function sync(g){desiredPos=g.players.map(p=>p.pos);active=g.active;won=g.phase==='won';board.beacons.forEach((b,i)=>{b.orb.material.emissiveIntensity=g.beacons[i]?1.2:.05;b.ring.material.color.set(g.beacons[i]?b.tint:'#69717d');});board.tiles.forEach((tile,i)=>{tile.material.emissive.set(i===g.players[g.active].pos?'#91ac80':'#000000');tile.material.emissiveIntensity=i===g.players[g.active].pos?.18:0;});}
function setPositions(){board.players.forEach((p,i)=>{const v=pointAt(desiredPos[i]);const same=desiredPos[0]===desiredPos[1];p.position.set(v.x+(same?(i===0?-.23:.23):0),.25,v.z+(same?.04:0));});}
function animateMove(player,from,to){return new Promise(resolve=>{if(calm){desiredPos[player]=to;setPositions();resolve();return;}animation={player,from,to,start:performance.now(),duration:Math.max(450,(to-from)*300),resolve};});}
function frame(){requestAnimationFrame(frame);const t=clock.getElapsedTime();board.players.forEach((p,i)=>{p.rotation.y=Math.sin(yaw)*.15+.12;const scale=.78*(i===active?1.025:1);const shape=p.userData.shapeScale||[1,1,1];p.scale.set(scale*shape[0],scale*shape[1],scale*shape[2]);});board.guardian.rotation.y=.1+Math.sin(t*.5)*(calm?0:.12);if(animation){const a=animation,k=Math.min(1,(performance.now()-a.start)/a.duration);const progress=a.from+(a.to-a.from)*k,idx=Math.floor(progress),next=Math.min(a.to,idx+1),f=progress-idx;const v=pointAt(idx).lerp(pointAt(next),f);board.players[a.player].position.set(v.x,.25+Math.sin(f*Math.PI)*.24,v.z);if(k>=1){animation=null;setPositions();a.resolve();}}else{setPositions();board.players.forEach((p,i)=>{if(!calm&&i===active&&!won)p.position.y+=Math.sin(t*2.5)*.012;});}renderer.render(scene,camera);}
frame();return {sync,animateMove,setCalm(v){calm=v;},toggleView(){overhead=!overhead;pitch=overhead?1.52:.87;yaw=overhead?0:-.16;distance=overhead?13.5:13.8;updateCamera();return overhead;},resetView(){overhead=false;yaw=-.16;pitch=.87;distance=13.8;updateCamera();},scene,board};}
export function initDie(container){const scene=new THREE.Scene();const renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;container.appendChild(renderer.domElement);const camera=new THREE.PerspectiveCamera(31,1,.1,30);camera.position.set(0,0,5.6);scene.add(new THREE.AmbientLight('#ffffff',2.3));const light=new THREE.DirectionalLight('#ffffff',4);light.position.set(-2,4,5);scene.add(light);const geo=new THREE.IcosahedronGeometry(.92,0);geo.computeVertexNormals();const die=new THREE.Group();const mats=[new THREE.MeshStandardMaterial({color:'#a3b692',roughness:.48,metalness:.15,flatShading:true})];const body=new THREE.Mesh(geo,mats[0]);die.add(body);const edges=new THREE.LineSegments(new THREE.EdgesGeometry(geo),new THREE.LineBasicMaterial({color:'#d2dfbe',transparent:true,opacity:.55}));die.add(edges);const faces=[],positions=geo.attributes.position;
for(let i=0;i<20;i++){const a=new THREE.Vector3().fromBufferAttribute(positions,i*3),b=new THREE.Vector3().fromBufferAttribute(positions,i*3+1),c=new THREE.Vector3().fromBufferAttribute(positions,i*3+2),center=a.clone().add(b).add(c).divideScalar(3),normal=center.clone().normalize();faces.push(normal);const sprite=new THREE.Mesh(new THREE.PlaneGeometry(.32,.32),new THREE.MeshBasicMaterial({map:labelTexture(String(i+1),null,'#26352d',128),transparent:true,depthWrite:false}));sprite.position.copy(center).addScaledVector(normal,.009);sprite.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),normal);die.add(sprite);}
scene.add(die);let raf=0,spinning=false;function resize(){if(!container.isConnected)return;const w=container.clientWidth,h=container.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();renderer.render(scene,camera);}const observer=new ResizeObserver(resize);observer.observe(container);let finalQ=new THREE.Quaternion().setFromUnitVectors(faces[19],new THREE.Vector3(0,0,1));die.quaternion.copy(finalQ);resize();
return {roll(value,calm=false){return new Promise(resolve=>{spinning=true;const start=performance.now(),from=die.quaternion.clone(),end=new THREE.Quaternion().setFromUnitVectors(faces[value-1],new THREE.Vector3(0,0,1));const duration=calm?1:1050;function tick(){const k=Math.min(1,(performance.now()-start)/duration);if(k<.7){die.rotation.set(k*24,k*19,k*11);}else{const f=(k-.7)/.3;die.quaternion.copy(from).slerp(end,f);}renderer.render(scene,camera);if(k<1)raf=requestAnimationFrame(tick);else{die.quaternion.copy(end);renderer.render(scene,camera);spinning=false;resolve();}}tick();});},set(value){die.quaternion.setFromUnitVectors(faces[(value||20)-1],new THREE.Vector3(0,0,1));renderer.render(scene,camera);},dispose(){cancelAnimationFrame(raf);observer.disconnect();scene.traverse(o=>{o.geometry?.dispose();if(o.material){for(const m of [o.material].flat()){m.map?.dispose();m.dispose();}}});renderer.dispose();renderer.domElement.remove();}};}

